// Deterministic renderer for the small hardware generated by a mission plan.
// Player-installed payloads remain ordinary hero meshes; this module batches
// only the supporting boxes, brackets, radiator fins, cable clamps and fasteners.

import * as THREE from 'three';

export const INSTALLATION_KINDS = Object.freeze([
  'auxBox',
  'support',
  'radiatorFin',
  'clamp',
  'fastener',
]);

const KIND_ALIASES = Object.freeze({
  auxbox: 'auxBox', box: 'auxBox', auxiliarybox: 'auxBox', equipmentbox: 'auxBox',
  support: 'support', bracket: 'support', supportbracket: 'support', mount: 'support',
  radiator: 'radiatorFin', radiatorfin: 'radiatorFin', fin: 'radiatorFin', louver: 'radiatorFin',
  clamp: 'clamp', cableclamp: 'clamp', harnessclamp: 'clamp',
  fastener: 'fastener', bolt: 'fastener', screw: 'fastener', rivet: 'fastener',
});

const MISSION_ALIASES = Object.freeze({
  weather: 'weather', cloud: 'weather', clouds: 'weather', meteorology: 'weather',
  ocean: 'ocean', sea: 'ocean', marine: 'ocean',
  communication: 'communication', communications: 'communication', comms: 'communication',
});

const DEFAULT_RESERVE = 0.20;
const TAU = Math.PI * 2;
const ZERO_MATRIX = new THREE.Matrix4().makeScale(0, 0, 0);
const WORK_MATRIX = new THREE.Matrix4();
const WORK_POSITION = new THREE.Vector3();
const WORK_SCALE = new THREE.Vector3();
const WORK_FACTOR = new THREE.Vector3();
const WORK_QUATERNION = new THREE.Quaternion();
const EXTRA_QUATERNION = new THREE.Quaternion();
const Y_AXIS = new THREE.Vector3(0, 1, 0);
const Z_AXIS = new THREE.Vector3(0, 0, 1);

const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));

function smooth(value) {
  const t = clamp01(value);
  return t * t * (3 - 2 * t);
}

function normalizeMission(value) {
  const key = String(value || 'weather').trim().toLowerCase();
  return MISSION_ALIASES[key] || 'weather';
}

function canonicalKind(value) {
  const key = String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return KIND_ALIASES[key] || null;
}

function hashSeed(value) {
  const text = String(value ?? 'satellite-installation');
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function deterministicUnit(value) {
  let state = hashSeed(value);
  state += 0x6D2B79F5;
  let result = state;
  result = Math.imul(result ^ (result >>> 15), result | 1);
  result ^= result + Math.imul(result ^ (result >>> 7), result | 61);
  return ((result ^ (result >>> 14)) >>> 0) / 4294967296;
}

function extractEntries(plan, mission) {
  if (Array.isArray(plan)) return plan;
  if (!plan || typeof plan !== 'object') return [];

  const direct = [plan.autoEntries, plan.automaticEntries, plan.installationEntries, plan.auto];
  for (const candidate of direct) if (Array.isArray(candidate)) return candidate;

  const missionContainers = [plan.missions, plan.byMission, plan.missionPlans];
  for (const container of missionContainers) {
    if (container && typeof container === 'object' && container[mission]) {
      return extractEntries(container[mission], mission);
    }
  }
  if (plan[mission]) return extractEntries(plan[mission], mission);
  if (Array.isArray(plan.entries)) {
    // When a combined plan is supplied, consume explicit automatic records or
    // records whose kind belongs to this renderer. Manual hero modules are ignored.
    const automatic = plan.entries.filter((entry) => entry?.auto === true || entry?.automatic === true);
    if (automatic.length) return automatic;
    return plan.entries.filter((entry) => canonicalKind(entry?.kind ?? entry?.type));
  }
  return [];
}

function finiteVector3(value, fallback = null) {
  if (value?.isVector3) return value.clone();
  if (Array.isArray(value) && value.length >= 3 && value.slice(0, 3).every(Number.isFinite)) {
    return new THREE.Vector3(value[0], value[1], value[2]);
  }
  if (value && [value.x, value.y, value.z].every(Number.isFinite)) {
    return new THREE.Vector3(value.x, value.y, value.z);
  }
  return fallback ? fallback.clone() : null;
}

function finiteScale(value) {
  if (Number.isFinite(value)) return new THREE.Vector3(value, value, value);
  return finiteVector3(value);
}

function finiteQuaternion(entry) {
  const value = entry?.quaternion;
  if (value?.isQuaternion) return value.clone().normalize();
  if (Array.isArray(value) && value.length >= 4 && value.slice(0, 4).every(Number.isFinite)) {
    return new THREE.Quaternion(value[0], value[1], value[2], value[3]).normalize();
  }
  const rotation = entry?.rotation;
  if (rotation?.isEuler) return new THREE.Quaternion().setFromEuler(rotation);
  if (Array.isArray(rotation) && rotation.length >= 3 && rotation.slice(0, 3).every(Number.isFinite)) {
    return new THREE.Quaternion().setFromEuler(new THREE.Euler(rotation[0], rotation[1], rotation[2]));
  }
  return new THREE.Quaternion();
}

function defaultDelay(mission, kind, id, index) {
  const base = {
    support: 0.00,
    auxBox: 0.12,
    radiatorFin: 0.28,
    clamp: 0.42,
    fastener: 0.54,
  }[kind];
  return base + index * 0.018 + deterministicUnit(`${mission}|${kind}|${id}|${index}`) * 0.055;
}

function normalizeRecord(entry, index, mission, revealDuration) {
  const kind = canonicalKind(entry?.kind ?? entry?.type);
  if (!kind) throw new TypeError(`entries[${index}] has an unsupported kind`);
  const position = finiteVector3(entry.position);
  if (!position) throw new TypeError(`entries[${index}].position must contain three finite numbers`);
  const scale = finiteScale(entry.scale ?? entry.size ?? entry.dimensions ?? 1);
  if (!scale || Math.min(scale.x, scale.y, scale.z) <= 0) {
    throw new TypeError(`entries[${index}].scale must be positive`);
  }
  const id = typeof entry.id === 'string' && entry.id ? entry.id : `${kind}-${index + 1}`;
  const delay = Number.isFinite(entry.delay)
    ? Math.max(0, entry.delay)
    : defaultDelay(mission, kind, id, index);
  const duration = Number.isFinite(entry.duration)
    ? Math.max(0.08, entry.duration)
    : revealDuration;
  const colorHex = Number.isInteger(entry.colorHex) && entry.colorHex >= 0 && entry.colorHex <= 0xffffff
    ? entry.colorHex
    : 0xffffff;

  return {
    id,
    kind,
    position,
    quaternion: finiteQuaternion(entry),
    scale,
    colorHex,
    delay,
    duration,
    zone: typeof entry.zone === 'string' && entry.zone ? entry.zone : 'satellite-bus',
    role: typeof entry.role === 'string' && entry.role ? entry.role : kind,
    instanceId: -1,
    progress: 0,
  };
}

function resolveMaterial(source, names, factory, owned) {
  for (const name of names) if (source?.[name]?.isMaterial) return source[name];
  const material = factory();
  owned.add(material);
  return material;
}

function makeSupportGeometry() {
  // A shallow extruded L is legible as a mounting bracket even at mobile scale.
  const shape = new THREE.Shape();
  shape.moveTo(-0.5, -0.5);
  shape.lineTo(0.5, -0.5);
  shape.lineTo(0.5, -0.25);
  shape.lineTo(-0.22, -0.25);
  shape.lineTo(-0.22, 0.5);
  shape.lineTo(-0.5, 0.5);
  shape.closePath();
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: 1,
    steps: 1,
    bevelEnabled: true,
    bevelSegments: 1,
    bevelSize: 0.035,
    bevelThickness: 0.035,
  });
  geometry.translate(0, 0, -0.5);
  geometry.computeVertexNormals();
  return geometry;
}

function createGeometries() {
  // Mission plans express final dimensions in their scale triples. Keeping the
  // source meshes at unit size prevents a second, accidental size reduction.
  const clamp = new THREE.TorusGeometry(0.38, 0.12, 7, 16, Math.PI * 1.68);
  clamp.rotateX(Math.PI / 2);
  return {
    auxBox: new THREE.BoxGeometry(1, 1, 1),
    support: makeSupportGeometry(),
    radiatorFin: new THREE.BoxGeometry(1, 1, 1),
    clamp,
    fastener: new THREE.CylinderGeometry(0.5, 0.5, 1, 8),
  };
}

/** Validate raw automatic entries without touching Three.js scene state. */
export function validatePlannedSatelliteInstallationPlan(plan, {
  mission = plan?.mission ?? 'weather',
  reserveRatio = DEFAULT_RESERVE,
} = {}) {
  const normalizedMission = normalizeMission(mission);
  const issues = [];
  const entries = extractEntries(plan, normalizedMission);
  if (!Array.isArray(entries)) issues.push('automatic entries must be an array');
  const byKind = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));

  (entries || []).forEach((entry, index) => {
    const kind = canonicalKind(entry?.kind ?? entry?.type);
    if (!kind) {
      issues.push(`entries[${index}] has an unsupported kind`);
      return;
    }
    byKind[kind] += 1;
    if (!finiteVector3(entry.position)) issues.push(`entries[${index}].position is invalid`);
    const scale = finiteScale(entry.scale ?? entry.size ?? entry.dimensions ?? 1);
    if (!scale || Math.min(scale.x, scale.y, scale.z) <= 0) issues.push(`entries[${index}].scale is invalid`);
    if (entry.delay != null && (!Number.isFinite(entry.delay) || entry.delay < 0)) {
      issues.push(`entries[${index}].delay is invalid`);
    }
  });

  const ratio = Number.isFinite(reserveRatio) && reserveRatio >= 0 ? reserveRatio : DEFAULT_RESERVE;
  const capacity = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, {
    required: byKind[kind],
    withReserve: Math.ceil(byKind[kind] * (1 + ratio)),
  }]));
  return Object.freeze({
    valid: issues.length === 0,
    issues: Object.freeze(issues),
    mission: normalizedMission,
    used: entries.length,
    byKind: Object.freeze(byKind),
    capacity: Object.freeze(capacity),
  });
}

export class PlannedSatelliteInstallation {
  constructor(parent, {
    plan = null,
    mission = null,
    materials = {},
    reserveRatio = DEFAULT_RESERVE,
    revealDuration = 0.46,
    autoReveal = false,
    startTime = 0,
  } = {}) {
    if (!parent?.isObject3D || typeof parent.add !== 'function') {
      throw new TypeError('PlannedSatelliteInstallation requires a THREE.Object3D parent');
    }
    if (!Number.isFinite(reserveRatio) || reserveRatio < 0) {
      throw new RangeError('reserveRatio must be a non-negative number');
    }
    if (!Number.isFinite(revealDuration) || revealDuration <= 0) {
      throw new RangeError('revealDuration must be positive');
    }

    this.parent = parent;
    this.root = new THREE.Group();
    this.root.name = 'planned-satellite-installation';
    parent.add(this.root);
    this.mission = normalizeMission(mission ?? plan?.mission ?? 'weather');
    this.reserveRatio = reserveRatio;
    this.revealDuration = revealDuration;
    this._ownedMaterials = new Set();
    this._geometries = {};
    this.meshes = {};
    this._records = [];
    this._byKind = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));
    this._byZone = {};
    this._byRole = {};
    this._capacities = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));
    this._validationIssues = [];
    this._revealing = false;
    this._complete = false;
    this._revealStart = null;
    this._timelineDuration = 0;
    this._disposed = false;

    this.materials = Object.freeze({
      auxBox: resolveMaterial(materials, ['auxBox', 'aluminium', 'whitePaint', 'paintedAluminium'], () => new THREE.MeshPhysicalMaterial({
        color: 0xdfe8ec, roughness: 0.42, metalness: 0.23, clearcoat: 0.06,
      }), this._ownedMaterials),
      support: resolveMaterial(materials, ['support', 'rail', 'aluminiumDark', 'structuralMetal', 'frame'], () => new THREE.MeshStandardMaterial({
        color: 0x8f9ba4, roughness: 0.34, metalness: 0.78,
      }), this._ownedMaterials),
      radiatorFin: resolveMaterial(materials, ['radiatorFin', 'blackRadiator', 'radiator'], () => new THREE.MeshStandardMaterial({
        color: 0x10161d, roughness: 0.78, metalness: 0.25,
      }), this._ownedMaterials),
      clamp: resolveMaterial(materials, ['clamp', 'harnessClamp', 'rail', 'structuralMetal'], () => new THREE.MeshStandardMaterial({
        color: 0x71828e, roughness: 0.4, metalness: 0.65,
      }), this._ownedMaterials),
      fastener: resolveMaterial(materials, ['fastener', 'aluminiumDark', 'rail', 'structuralMetal', 'frame'], () => new THREE.MeshStandardMaterial({
        color: 0xb6c0c6, roughness: 0.28, metalness: 0.82,
      }), this._ownedMaterials),
    });

    if (plan != null) {
      this.install(plan, { mission: this.mission });
      if (autoReveal) this.reveal(startTime);
    }
  }

  _clearMeshes() {
    for (const mesh of Object.values(this.meshes)) this.root.remove(mesh);
    for (const geometry of Object.values(this._geometries)) geometry.dispose();
    this.meshes = {};
    this._geometries = {};
  }

  install(plan, { mission = plan?.mission ?? this.mission } = {}) {
    const nextMission = normalizeMission(mission);
    const validation = validatePlannedSatelliteInstallationPlan(plan, {
      mission: nextMission,
      reserveRatio: this.reserveRatio,
    });
    this._validationIssues = [...validation.issues];
    if (!validation.valid) {
      throw new TypeError(`Invalid satellite installation plan: ${validation.issues.join('; ')}`);
    }

    // Normalize every record before changing the visible pools. An invalid late
    // entry therefore cannot leave a half-installed satellite in the scene.
    const entries = extractEntries(plan, nextMission);
    const records = entries.map((entry, index) => normalizeRecord(
      entry, index, nextMission, this.revealDuration,
    ));

    this._clearMeshes();
    this.mission = nextMission;
    this._geometries = createGeometries();
    this._records = records;
    this._byKind = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));
    this._byZone = {};
    this._byRole = {};
    this._capacities = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [
      kind,
      Math.ceil(validation.byKind[kind] * (1 + this.reserveRatio)),
    ]));

    for (const kind of INSTALLATION_KINDS) {
      // Three requires a positive constructor capacity. Unused kinds remain at
      // count=0 and report a logical capacity of zero through stats.
      const physicalCapacity = Math.max(1, this._capacities[kind]);
      const mesh = new THREE.InstancedMesh(
        this._geometries[kind],
        this.materials[kind],
        physicalCapacity,
      );
      mesh.name = `planned-satellite-${kind}`;
      mesh.count = validation.byKind[kind];
      mesh.frustumCulled = false;
      mesh.castShadow = kind === 'auxBox' || kind === 'support';
      mesh.receiveShadow = kind === 'auxBox';
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      this.root.add(mesh);
      this.meshes[kind] = mesh;
    }

    const nextInstance = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));
    for (const record of records) {
      const mesh = this.meshes[record.kind];
      record.instanceId = nextInstance[record.kind]++;
      mesh.setMatrixAt(record.instanceId, ZERO_MATRIX);
      mesh.setColorAt(record.instanceId, new THREE.Color(record.colorHex));
      this._byKind[record.kind] += 1;
      this._byZone[record.zone] = (this._byZone[record.zone] || 0) + 1;
      this._byRole[record.role] = (this._byRole[record.role] || 0) + 1;
    }

    for (const kind of INSTALLATION_KINDS) {
      const mesh = this.meshes[kind];
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    }

    this._timelineDuration = records.reduce(
      (maximum, record) => Math.max(maximum, record.delay + record.duration),
      0,
    );
    this._revealing = false;
    this._complete = records.length === 0;
    this._revealStart = null;
    return this.stats;
  }

  reveal(startTime = 0) {
    if (!Number.isFinite(startTime)) throw new TypeError('reveal startTime must be finite');
    for (const record of this._records) record.progress = 0;
    for (const kind of INSTALLATION_KINDS) {
      const mesh = this.meshes[kind];
      if (!mesh) continue;
      for (let index = 0; index < mesh.count; index += 1) mesh.setMatrixAt(index, ZERO_MATRIX);
      mesh.instanceMatrix.needsUpdate = true;
      mesh.frustumCulled = false;
    }
    this._revealStart = startTime;
    this._revealing = this._records.length > 0;
    this._complete = this._records.length === 0;
    return this.stats;
  }

  _matrixFor(record, rawProgress) {
    const progress = smooth(rawProgress);
    WORK_POSITION.copy(record.position);
    WORK_SCALE.copy(record.scale);
    WORK_QUATERNION.copy(record.quaternion);

    if (record.kind === 'auxBox') {
      const growth = 0.08 + progress * 0.92;
      WORK_SCALE.multiplyScalar(growth);
      WORK_POSITION.y += (1 - progress) * 0.08;
    } else if (record.kind === 'support') {
      WORK_FACTOR.set(0.25 + progress * 0.75, progress, 0.55 + progress * 0.45);
      WORK_SCALE.multiply(WORK_FACTOR);
    } else if (record.kind === 'radiatorFin') {
      WORK_FACTOR.set(0.05 + progress * 0.95, 0.65 + progress * 0.35, 1);
      WORK_SCALE.multiply(WORK_FACTOR);
      EXTRA_QUATERNION.setFromAxisAngle(Z_AXIS, (1 - progress) * 0.34);
      WORK_QUATERNION.multiply(EXTRA_QUATERNION);
    } else if (record.kind === 'clamp') {
      const growth = 0.15 + progress * 0.85;
      WORK_SCALE.multiplyScalar(growth);
      EXTRA_QUATERNION.setFromAxisAngle(Y_AXIS, (1 - progress) * Math.PI * 0.35);
      WORK_QUATERNION.multiply(EXTRA_QUATERNION);
    } else {
      // Fasteners visibly turn during their short seating motion.
      WORK_FACTOR.set(0.35 + progress * 0.65, progress, 0.35 + progress * 0.65);
      WORK_SCALE.multiply(WORK_FACTOR);
      EXTRA_QUATERNION.setFromAxisAngle(Y_AXIS, (1 - progress) * TAU);
      WORK_QUATERNION.multiply(EXTRA_QUATERNION);
    }

    WORK_MATRIX.compose(WORK_POSITION, WORK_QUATERNION, WORK_SCALE);
    return WORK_MATRIX;
  }

  update(time) {
    if (!Number.isFinite(time) || !this._revealing || this._revealStart == null) return this._complete;
    const elapsed = Math.max(0, time - this._revealStart);
    const touched = new Set();
    let allComplete = true;

    for (const record of this._records) {
      if (record.progress >= 1) continue;
      const raw = (elapsed - record.delay) / record.duration;
      if (raw <= 0) {
        allComplete = false;
        continue;
      }
      const progress = clamp01(raw);
      this.meshes[record.kind].setMatrixAt(
        record.instanceId,
        this._matrixFor(record, progress),
      );
      record.progress = progress;
      touched.add(record.kind);
      if (progress < 1) allComplete = false;
    }

    for (const kind of touched) this.meshes[kind].instanceMatrix.needsUpdate = true;
    if (allComplete) this._finishReveal();
    return this._complete;
  }

  setRevealProgress(value) {
    const progress = clamp01(value);
    const elapsed = this._timelineDuration * progress;
    const touched = new Set();
    for (const record of this._records) {
      const local = clamp01((elapsed - record.delay) / record.duration);
      record.progress = local;
      if (local <= 0) {
        this.meshes[record.kind].setMatrixAt(record.instanceId, ZERO_MATRIX);
      } else {
        this.meshes[record.kind].setMatrixAt(record.instanceId, this._matrixFor(record, local));
      }
      touched.add(record.kind);
    }
    for (const kind of touched) this.meshes[kind].instanceMatrix.needsUpdate = true;
    this._revealing = progress < 1 && this._records.length > 0;
    this._complete = progress >= 1 || this._records.length === 0;
    if (this._complete) this._finishReveal();
    return this.stats;
  }

  completeInstantly() { return this.setRevealProgress(1); }

  _finishReveal() {
    this._complete = true;
    this._revealing = false;
    for (const mesh of Object.values(this.meshes)) {
      mesh.computeBoundingSphere?.();
      mesh.frustumCulled = true;
    }
  }

  setVisible(value) {
    this.root.visible = !!value;
    return this.stats;
  }

  /** Clear generated support hardware so a replay can load a fresh mission. */
  reset() {
    this._clearMeshes();
    this.root.visible = true;
    this._records = [];
    this._byKind = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));
    this._byZone = {};
    this._byRole = {};
    this._capacities = Object.fromEntries(INSTALLATION_KINDS.map((kind) => [kind, 0]));
    this._validationIssues = [];
    this._revealing = false;
    this._complete = false;
    this._revealStart = null;
    this._timelineDuration = 0;
    return this.stats;
  }

  get stats() {
    const byKindCapacity = {};
    let totalCapacity = 0;
    for (const kind of INSTALLATION_KINDS) {
      const used = this._byKind[kind] || 0;
      const capacity = this._capacities[kind] || 0;
      totalCapacity += capacity;
      byKindCapacity[kind] = Object.freeze({
        used,
        required: used,
        capacity,
        remaining: capacity - used,
        overflow: Math.max(0, used - capacity),
      });
    }
    const revealed = this._records.filter((record) => record.progress >= 1).length;
    const averageProgress = this._records.length
      ? this._records.reduce((sum, record) => sum + record.progress, 0) / this._records.length
      : 1;
    const capacityOverflow = Object.values(byKindCapacity).reduce((sum, item) => sum + item.overflow, 0);

    return Object.freeze({
      mission: this.mission,
      visible: this.root.visible,
      loaded: Object.keys(this.meshes).length === INSTALLATION_KINDS.length,
      used: this._records.length,
      revealed,
      progress: +averageProgress.toFixed(4),
      revealing: this._revealing,
      complete: this._complete,
      byKind: Object.freeze({ ...this._byKind }),
      byZone: Object.freeze({ ...this._byZone }),
      byRole: Object.freeze({ ...this._byRole }),
      capacity: Object.freeze({
        reserveRatio: this.reserveRatio,
        total: totalCapacity,
        used: this._records.length,
        remaining: totalCapacity - this._records.length,
        overflow: capacityOverflow,
        withinLimits: capacityOverflow === 0,
        byKind: Object.freeze(byKindCapacity),
      }),
      validation: Object.freeze({
        valid: this._validationIssues.length === 0,
        issues: Object.freeze([...this._validationIssues]),
      }),
    });
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    this._clearMeshes();
    for (const material of this._ownedMaterials) material.dispose();
    this.parent.remove(this.root);
    this.root.clear();
  }
}
